    10	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    11	public final class ReservationService {
    12	
    13	    static final String HOTEL_NAME = "Pousada Maré Alta";
    14	
    15	    private final Rooms rooms;
    16	    private final ReservationStore store;
    17	    private final PriceCalculator priceCalculator;
    18	    private final EmailSender emailSender;
    19	    private final List<ReservationEventListener> listeners;
    20	
    21	    public ReservationService(
    22	            Rooms rooms,
    23	            ReservationStore store,
    24	            PriceCalculator priceCalculator,
    25	            EmailSender emailSender,
    26	            List<ReservationEventListener> listeners) {
    27	        this.rooms = rooms;
    28	        this.store = store;
    29	        this.priceCalculator = priceCalculator;
    30	        this.emailSender = emailSender;
    31	        this.listeners = List.copyOf(listeners);
    32	    }
    33	
    34	    public synchronized Reservation create(NewReservation request) {
    35	        if (!request.checkOut().isAfter(request.checkIn())) {
    36	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    37	        }
    38	        if (request.guests() < 1) {
    39	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    40	        }
    41	        Room room = rooms.find(request.roomNumber())
    42	                .orElseThrow(() -> new HotelException(
    43	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    44	        if (request.guests() > room.capacity()) {
    45	            throw new HotelException(
    46	                    ErrorCode.CAPACITY_EXCEEDED,
    47	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    48	        }
    49	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    50	            throw new HotelException(
    51	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    52	        }
    53	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    54	        return store.add(request, price);
    55	    }
    56	
    57	    public Reservation find(long reservationId) {
    58	        return store.find(reservationId)
    59	                .orElseThrow(() -> new HotelException(
    60	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    61	    }
    62	
    63	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    64	    public synchronized Reservation confirm(long reservationId) {
    65	        Reservation reservation = find(reservationId);
    66	        if (reservation.status() != ReservationStatus.PENDING) {
    67	            throw notAllowed(reservation, "confirm");
    68	        }
    69	        reservation.confirmPayment();
    70	        store.update(reservation);
    71	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    72	        emailSender.send(
    73	                reservation.guest().email(),
    74	                "Reserva confirmada - " + HOTEL_NAME,
    75	                confirmationEmailBody(reservation, receipt));
    76	        Room room = roomOf(reservation);
    77	        for (ReservationEventListener listener : listeners) {
    78	            listener.onReservationConfirmed(new ReservationConfirmedEvent(reservation, room));
    79	        }
    80	        return reservation;
    81	    }
    82	
    83	    /**
    84	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    85	     * reservation was never paid, so nothing comes back).
    86	     */
    87	    public synchronized Reservation cancel(long reservationId) {
    88	        Reservation reservation = find(reservationId);
    89	        if (reservation.status() != ReservationStatus.PENDING
    90	                && reservation.status() != ReservationStatus.CONFIRMED) {
    91	            throw notAllowed(reservation, "cancel");
    92	        }
    93	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    94	        BigDecimal refund = switch (reservation.ratePlan()) {
    95	            case STANDARD -> reservation.amountPaid();
    96	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    97	        };
    98	        reservation.cancel(refund);
    99	        store.update(reservation);
   100	        if (wasConfirmed) {
   101	            Room room = roomOf(reservation);
   102	            for (ReservationEventListener listener : listeners) {
   103	                listener.onReservationCancelled(new ReservationCancelledEvent(reservation, room, refund));
   104	            }
   105	        }
   106	        return reservation;
   107	    }
   108	
   109	    public synchronized Reservation checkIn(long reservationId) {
   110	        Reservation reservation = find(reservationId);
   111	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   112	            throw notAllowed(reservation, "check in");
   113	        }
   114	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   115	        store.update(reservation);
   116	        return reservation;
   117	    }
   118	
   119	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   120	    public synchronized ReservationReceipt checkOut(long reservationId) {
   121	        Reservation reservation = find(reservationId);
   122	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   123	            throw notAllowed(reservation, "check out");
   124	        }
   125	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   126	        store.update(reservation);
   127	        return new ReservationReceipt(reservation, roomOf(reservation));
   128	    }
   129	
   130	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   131	    public ReservationReceipt receiptCopy(long reservationId) {
   132	        Reservation reservation = find(reservationId);
   133	        if (!reservation.isPaid()) {
   134	            throw notAllowed(reservation, "issue a receipt for");
   135	        }
   136	        return new ReservationReceipt(reservation, roomOf(reservation));
   137	    }
   138	
   139	    private Room roomOf(Reservation reservation) {
   140	        return rooms.find(reservation.roomNumber()).orElseThrow();
   141	    }
   142	
   143	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   144	        return "Olá, " + reservation.guest().name() + "!\n\n"
   145	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   146	                + receipt.text() + "\n"
   147	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   148	                + "Até breve!\n";
   149	    }
   150	
   151	    private static HotelException notAllowed(Reservation reservation, String operation) {
   152	        return new HotelException(
   153	                ErrorCode.OPERATION_NOT_ALLOWED,
   154	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   155	    }
   156	}
