    91	            throw notAllowed(reservation, "cancel");
    92	        }
    93	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    94	        BigDecimal refund = switch (reservation.ratePlan()) {
    95	            case STANDARD -> reservation.amountPaid();
    96	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    97	        };
    98	        reservation.cancel(refund);
    99	        store.update(reservation);
   100	        if (wasConfirmed) {
   101	            Room room = roomOf(reservation);
   102	            for (ReservationEventListener listener : listeners) {
   103	                listener.onReservationCancelled(new ReservationCancelledEvent(reservation, room, refund));
   104	            }
   105	        }
   106	        return reservation;
   107	    }
   108	
   109	    public synchronized Reservation checkIn(long reservationId) {
   110	        Reservation reservation = find(reservationId);
   111	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   112	            throw notAllowed(reservation, "check in");
   113	        }
   114	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   115	        store.update(reservation);
   116	        return reservation;
   117	    }
   118	
   119	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   120	    public synchronized ReservationReceipt checkOut(long reservationId) {
   121	        Reservation reservation = find(reservationId);
   122	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   123	            throw notAllowed(reservation, "check out");
   124	        }
   125	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   126	        store.update(reservation);
   127	        return new ReservationReceipt(reservation, roomOf(reservation));
   128	    }
   129	
   130	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   131	    public ReservationReceipt receiptCopy(long reservationId) {
   132	        Reservation reservation = find(reservationId);
   133	        if (!reservation.isPaid()) {
   134	            throw notAllowed(reservation, "issue a receipt for");
   135	        }
   136	        return new ReservationReceipt(reservation, roomOf(reservation));
   137	    }
   138	
   139	    private Room roomOf(Reservation reservation) {
   140	        return rooms.find(reservation.roomNumber()).orElseThrow();
   141	    }
   142	
   143	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   144	        return "Olá, " + reservation.guest().name() + "!\n\n"
   145	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   146	                + receipt.text() + "\n"
   147	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   148	                + "Até breve!\n";
   149	    }
   150	
   151	    private static HotelException notAllowed(Reservation reservation, String operation) {
   152	        return new HotelException(
   153	                ErrorCode.OPERATION_NOT_ALLOWED,
   154	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   155	    }
